def compute(vars):
    old = vars["v1"]
    new = vars["v2"]

    if old == 0:
        return None

    change_ratio = (new - old) / old
    percentage_increase = change_ratio * 100

    return {
        "value": percentage_increase,
        "trace": {
            "old_maturity_amount": old,
            "new_maturity_amount": new,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
